def is_bst(root):
    def valid(node, lo, hi):
        if node is None:
            return True
        if node.val < lo or node.val > hi:
            return False
        return (valid(node.left, lo, node.val) and
                valid(node.right, node.val, hi))
    return valid(root, float('-inf'), float('inf'))
```

