def int_to_string(n):
    if n == 0:
        return "0"
    sign = "-" if n < 0 else ""
    n = abs(n)
    chars = []
    while n > 0:
        chars.append(chr(ord('0') + (n % 10)))
        n //= 10
    chars.reverse()
    return sign + "".join(chars)
```

