def caesar_cipher(text, shift, alphabet="abcdefghijklmnopqrstuvwxyz"):
    output = ''
    for ch in text.lower():
        if ch in alphabet:
            idx = alphabet.find(ch)
            new_idx = (idx + shift) % len(alphabet)
            output += alphabet[new_idx]
        else:
            output += ch
    return output
```

