```python
def selection_sort(arr):
    n = len(arr)
    for i in range(n):
        min_index = i
        for j in range(i + 1, n):
            if arr[j] < arr[min_index]:
                min_index = j
        arr[i], arr[min_index] = arr[min_index], arr[i]
    return arr
```

import math

def std_dev(numbers):
    count = len(numbers)
    if count == 0:
        return 0
    mean = sum(numbers) / count
    variance = sum((x - mean) ** 2 for x in numbers) / count
    return math.sqrt(variance)

